<!-- Props: themes, themeStats, search?, rateBusyId?, isGuest?, showFullPageChrome?, onPickTheme?; Emits: update:search, update:rateBusyId; Slots: —; Exposed: — -->
<script setup lang="ts">
import { computed } from 'vue'
import { api } from '$lib/api'
import { refreshApp } from '$lib/appStore'
import type { Theme, ThemeStat } from '$lib/types'
import ThemeStars from './ThemeStars.vue'
import ThemeDirectoryRow from './ThemeDirectoryRow.vue'
const props=withDefaults(defineProps<{themes:Theme[];themeStats:Record<string,ThemeStat|undefined>;search?:string;rateBusyId?:string|null;isGuest?:boolean;showFullPageChrome?:boolean;onPickTheme?:(id:string)=>void}>(),{search:'',rateBusyId:null,isGuest:false,showFullPageChrome:false})
const emit=defineEmits<{ 'update:search':[value:string]; 'update:rateBusyId':[value:string|null] }>()
const search=computed({get:()=>props.search??'',set:(value:string)=>emit('update:search',value)})
const query=computed(()=>search.value.trim().toLowerCase())
const filtered=computed(()=>{const q=query.value;const list=q?props.themes.filter(t=>t.name.toLowerCase().includes(q)||t.id.toLowerCase().includes(q)||t.emoji.includes(q)||(t.tags?.some(tag=>tag.includes(q))??false)):props.themes;return [...list].sort((a,b)=>{const x=props.themeStats[a.id],y=props.themeStats[b.id];return(y?.questionCount??0)-(x?.questionCount??0)||(y?.ratingAvg??0)-(x?.ratingAvg??0)||a.name.localeCompare(b.name,'fr')})})
const tags=computed(()=>[...new Set(props.themes.flatMap(t=>t.tags??[]))].sort((a,b)=>a.localeCompare(b,'fr')))
const groups=computed(()=>tags.value.map(tag=>({tag,label:tag.split('-').filter(Boolean).map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' '),themes:filtered.value.filter(t=>t.tags?.includes(tag))})).filter(g=>g.themes.length))
const untagged=computed(()=>filtered.value.filter(t=>!t.tags?.length));const popular=computed(()=>filtered.value.slice(0,6))
function stat(t:Theme):ThemeStat{return props.themeStats[t.id]??{questionCount:0,ratingAvg:null,ratingCount:0,myStars:null}}
async function rate(themeId:string,stars:number){if(props.isGuest||props.rateBusyId)return;emit('update:rateBusyId',themeId);try{await api(`/themes/${encodeURIComponent(themeId)}/rate`,{method:'POST',body:{stars}});await refreshApp()}catch{/* keep browsing available if the rating request fails */}finally{emit('update:rateBusyId',null)}}
</script>
<template>
<div class="theme-directory"><div v-if="showFullPageChrome" class="page-heading"><span class="eyebrow">Bibliothèque</span><h1>Thèmes</h1><p>Recherche, aperçu des plus joués, notes et thèmes regroupés par tag.</p></div><label class="sr-only" for="theme-directory-search">Rechercher un thème</label><input id="theme-directory-search" v-model="search" type="search" placeholder="Rechercher un thème ou un tag…" autocomplete="off"/>
<section v-if="!query" class="popular"><h2 class="section-label">Populaires</h2><div class="theme-grid"><template v-for="theme in popular" :key="theme.id"><button v-if="onPickTheme" type="button" class="theme-tile surface" @click="onPickTheme(theme.id)"><img v-if="theme.coverImageUrl" :src="theme.coverImageUrl" alt="" loading="lazy"/><span v-else class="theme-tile__emoji">{{theme.emoji}}</span><span class="theme-tile__body"><strong>{{theme.emoji}} {{theme.name}}</strong><small>{{stat(theme).questionCount}} question{{stat(theme).questionCount===1?'':'s'}}</small><ThemeStars :avg="stat(theme).ratingAvg"/><small v-if="stat(theme).ratingCount">({{stat(theme).ratingCount}})</small></span></button><article v-else class="theme-tile surface"><img v-if="theme.coverImageUrl" :src="theme.coverImageUrl" alt="" loading="lazy"/><span v-else class="theme-tile__emoji">{{theme.emoji}}</span><span class="theme-tile__body"><strong>{{theme.emoji}} {{theme.name}}</strong><small>{{stat(theme).questionCount}} question{{stat(theme).questionCount===1?'':'s'}}</small><ThemeStars :avg="stat(theme).ratingAvg"/></span></article></template></div></section>
<template v-if="query"><h2 class="section-label">Résultats</h2><ul class="theme-list"><ThemeDirectoryRow v-for="t in filtered" :key="t.id" :theme="t" :stats="stat(t)" :is-guest="isGuest" :rate-busy-id="rateBusyId" :on-pick-theme="onPickTheme" :on-rate="(n:number)=>rate(t.id,n)"/></ul></template>
<template v-else-if="tags.length"><section v-for="group in groups" :key="group.tag" class="tag-group"><h2>{{group.label}}</h2><small><code>{{group.tag}}</code></small><ul class="theme-list"><ThemeDirectoryRow v-for="t in group.themes" :key="t.id" :theme="t" :stats="stat(t)" :is-guest="isGuest" :rate-busy-id="rateBusyId" :on-pick-theme="onPickTheme" :on-rate="(n:number)=>rate(t.id,n)"/></ul></section><section v-if="untagged.length" class="tag-group"><h2>Autres thèmes</h2><small>Aucun tag pour le moment</small><ul class="theme-list"><ThemeDirectoryRow v-for="t in untagged" :key="t.id" :theme="t" :stats="stat(t)" :is-guest="isGuest" :rate-busy-id="rateBusyId" :on-pick-theme="onPickTheme" :on-rate="(n:number)=>rate(t.id,n)"/></ul></section></template>
<template v-else><h2 class="section-label">Tous les thèmes</h2><ul class="theme-list"><ThemeDirectoryRow v-for="t in filtered" :key="t.id" :theme="t" :stats="stat(t)" :is-guest="isGuest" :rate-busy-id="rateBusyId" :on-pick-theme="onPickTheme" :on-rate="(n:number)=>rate(t.id,n)"/></ul></template><p v-if="!filtered.length" class="empty">Aucun thème trouvé.</p></div>
</template>
<style scoped>.theme-directory{display:grid;gap:16px}.section-label{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:1px}.popular,.tag-group{display:grid;gap:10px}.tag-group{margin-top:12px}.tag-group h2{font-size:16px}.tag-group>small{color:var(--muted)}.theme-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:12px}.theme-tile{display:grid;overflow:hidden;padding:0;color:var(--text);text-align:left}.theme-tile img,.theme-tile__emoji{display:grid;width:100%;height:100px;object-fit:cover;place-items:center;background:var(--primary-soft);font-size:32px}.theme-tile__body{display:grid;gap:5px;padding:10px}.theme-tile__body strong{font-size:13px}.theme-tile__body small{color:var(--muted)}.theme-list{display:grid;gap:8px;margin:0;padding:0;list-style:none}.empty{padding:28px;color:var(--muted);text-align:center}</style>
